    const bridge = new BrowserBridge();

    await expect(bridge.connect({ timeout: 0.1 })).rejects.toThrow('Browser Bridge extension not connected');
  });

  it('threads preferredContextId into every readiness health read', async () => {
    const { PKG_VERSION } = await import('./version.js');
    const spy = vi.spyOn(daemonTransport, 'getDaemonHealth').mockResolvedValue({
      state: 'no-extension',
      status: {
        ok: true,
        pid: 999999,
        uptime: 0,
        daemonVersion: PKG_VERSION,
        extensionConnected: false,
        pending: 0,
        memoryMB: 0,
        port: 0,
      },
    });

    const bridge = new BrowserBridge();

    await expect(bridge.connect({ timeout: 0.1, preferredContextId: 'zvypsyje' })).rejects.toThrow('Browser Bridge extension not connected');
    expect(spy.mock.calls.length).toBeGreaterThan(1);
    for (const call of spy.mock.calls) {
      expect(call[0]).toMatchObject({ preferredContextId: 'zvypsyje' });
    }
  });

  it('attempts stale daemon replacement when daemonVersion is missing', async () => {
    vi.spyOn(daemonTransport, 'getDaemonHealth').mockResolvedValue({
      state: 'no-extension',
      status: {
        ok: true,
        pid: 999999,
        uptime: 0,
        extensionConnected: false,
        pending: 0,
        memoryMB: 0,
        port: 0,
      },
    });
    vi.spyOn(daemonLifecycle.daemonLifecycleHooks, 'requestDaemonShutdown').mockResolvedValue(false);
    // Keep the SIGKILL fallback's poll short — neither pid 999999 nor the test
    // daemon exists, so we'd otherwise spin for 2s on every test in the block.
    vi.spyOn(daemonLifecycle.daemonLifecycleHooks, 'waitForDaemonStop').mockResolvedValue(false);

    const bridge = new BrowserBridge();

    await expect(bridge.connect({ timeout: 0.1 })).rejects.toThrow('Stale daemon could not be replaced');
  });

  it('attempts stale daemon replacement when daemonVersion mismatches', async () => {
    vi.spyOn(daemonTransport, 'getDaemonHealth').mockResolvedValue({
      state: 'no-extension',
      status: {
        ok: true,
        pid: 999999,
        uptime: 0,
        daemonVersion: '0.0.1',
        extensionConnected: false,
        pending: 0,
        memoryMB: 0,
        port: 0,
      },
    });
    vi.spyOn(daemonLifecycle.daemonLifecycleHooks, 'requestDaemonShutdown').mockResolvedValue(false);
    vi.spyOn(daemonLifecycle.daemonLifecycleHooks, 'waitForDaemonStop').mockResolvedValue(false);

    const bridge = new BrowserBridge();

    await expect(bridge.connect({ timeout: 0.1 })).rejects.toThrow('Stale daemon could not be replaced');
  });

  it('attempts stale daemon replacement even when extension is connected', async () => {
    vi.spyOn(daemonTransport, 'getDaemonHealth').mockResolvedValue({
      state: 'ready',
      status: {
        ok: true,
        pid: 999999,
        uptime: 0,
        daemonVersion: '0.0.1',
        extensionConnected: true,
        pending: 0,
        memoryMB: 0,
        port: 0,
      },
    });
    vi.spyOn(daemonLifecycle.daemonLifecycleHooks, 'requestDaemonShutdown').mockResolvedValue(false);
    vi.spyOn(daemonLifecycle.daemonLifecycleHooks, 'waitForDaemonStop').mockResolvedValue(false);

    const bridge = new BrowserBridge();

    await expect(bridge.connect({ timeout: 0.1 })).rejects.toThrow('Stale daemon could not be replaced');
  });

  it('falls back to SIGKILL when stale daemon refuses graceful shutdown', async () => {
    vi.spyOn(daemonTransport, 'getDaemonHealth').mockResolvedValue({
      state: 'no-extension',
      status: {
        ok: true,
        pid: 99999,
        uptime: 0,
        daemonVersion: '0.0.1',
        extensionConnected: false,
        pending: 0,
        memoryMB: 0,
        port: 0,
      },
    });
    vi.spyOn(daemonLifecycle.daemonLifecycleHooks, 'requestDaemonShutdown').mockResolvedValue(false);
    // Graceful shutdown short-circuits to false (requestDaemonShutdown -> false).
    // After SIGKILL the port is released, so the second waitForDaemonStop returns true.
    vi.spyOn(daemonLifecycle.daemonLifecycleHooks, 'waitForDaemonStop').mockResolvedValue(true);
    vi.spyOn(daemonLifecycle.daemonLifecycleHooks, 'spawnDaemonProcess').mockReturnValue(null as unknown as ReturnType<typeof daemonLifecycle.spawnDaemonProcess>);
    const killSpy = vi.spyOn(process, 'kill').mockImplementation(() => true);

    const bridge = new BrowserBridge();

    // We expect the stale-daemon path to succeed and then continue into the
    // no-extension wait (which times out with `timeout: 0.1`), producing the
    // extension-not-connected error rather than the stale-daemon error.
    await expect(bridge.connect({ timeout: 0.1 })).rejects.toThrow('Browser Bridge extension not connected');
    expect(killSpy).toHaveBeenCalledWith(99999, 'SIGKILL');
  });

  it('reports stale daemon error when SIGKILL fails to release the port', async () => {
    vi.spyOn(daemonTransport, 'getDaemonHealth').mockResolvedValue({
      state: 'no-extension',
      status: {
        ok: true,
        pid: 99999,
        uptime: 0,
        daemonVersion: '0.0.1',
        extensionConnected: false,
        pending: 0,
        memoryMB: 0,
        port: 0,
      },
    });
    vi.spyOn(daemonLifecycle.daemonLifecycleHooks, 'requestDaemonShutdown').mockResolvedValue(false);
    // Graceful + SIGKILL both fail to release the port.
    vi.spyOn(daemonLifecycle.daemonLifecycleHooks, 'waitForDaemonStop').mockResolvedValue(false);
    vi.spyOn(process, 'kill').mockImplementation(() => {
      throw Object.assign(new Error('EPERM'), { code: 'EPERM' });
    });

    const bridge = new BrowserBridge();

    await expect(bridge.connect({ timeout: 0.1 })).rejects.toThrow('Stale daemon could not be replaced');
  });
});

import * as fs from 'node:fs';
import * as os from 'node:os';
import * as path from 'node:path';
import { afterEach, describe, expect, it, vi } from 'vitest';
import { linkHostOpencli, resolveHostOpencliRoot } from './plugin-runtime.js';

vi.mock('node:fs', async (importOriginal) => ({ ...await importOriginal<typeof fs>() }));

const roots: string[] = [];
afterEach(() => {
  vi.restoreAllMocks();
  for (const root of roots.splice(0)) fs.rmSync(root, { recursive: true, force: true });
});
function fixture() {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), 'opencli-host-link-'));
  roots.push(root);
  const link = path.join(root, 'node_modules', '@jackwener', 'opencli');
  fs.mkdirSync(path.dirname(link), { recursive: true });
  return { root, link };
}
const type = process.platform === 'win32' ? 'junction' : 'dir';

describe('plugin host link repair', () => {
  it('leaves a correct link untouched on repeated discovery', () => {
    const { root, link } = fixture();
    fs.symlinkSync(resolveHostOpencliRoot(), link, type);
    const before = fs.lstatSync(link);
    const rename = vi.spyOn(fs, 'renameSync');
    const remove = vi.spyOn(fs, 'rmSync');
    expect(linkHostOpencli(root)).toBe(true);
    expect(linkHostOpencli(root)).toBe(true);
    expect(fs.lstatSync(link).ino).toBe(before.ino);
    expect(rename).not.toHaveBeenCalled();
    expect(remove).not.toHaveBeenCalled();
  });

  it.each([false, true])('atomically repairs a stale link, dangling=%s', (dangling) => {
    const { root, link } = fixture();
    const oldHost = path.join(root, 'old-host');
    if (!dangling) fs.mkdirSync(oldHost);
    fs.symlinkSync(oldHost, link, type);
    const rename = fs.renameSync;
    const publication = vi.spyOn(fs, 'renameSync').mockImplementation((from, to) => {
      expect(fs.lstatSync(link).isSymbolicLink()).toBe(true);
      expect(fs.readlinkSync(link)).toContain('old-host');
      rename(from, to);
    });
    expect(linkHostOpencli(root)).toBe(true);
    expect(publication).toHaveBeenCalledTimes(1);
    expect(fs.realpathSync(link)).toBe(fs.realpathSync(resolveHostOpencliRoot()));
    expect(fs.readdirSync(path.dirname(link))).toEqual(['opencli']);
  });

  it('preserves the old link and cleans up staging when publication fails', () => {
    const { root, link } = fixture();
    const oldHost = path.join(root, 'old-host');
    fs.mkdirSync(oldHost);
    fs.symlinkSync(oldHost, link, type);
    vi.spyOn(fs, 'renameSync').mockImplementation(() => { throw new Error('publication failed'); });
    expect(linkHostOpencli(root)).toBe(false);
    expect(fs.realpathSync(link)).toBe(fs.realpathSync(oldHost));
    expect(fs.readdirSync(path.dirname(link))).toEqual(['opencli']);
  });
});

import * as fs from 'node:fs';
import * as os from 'node:os';
import * as path from 'node:path';
import { describe, expect, it } from 'vitest';
import { ArgumentError } from './errors.js';
import { listOpenCliSkills, readOpenCliSkill } from './skills.js';

function makePackageRoot(): string {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), 'opencli-skills-'));
  fs.mkdirSync(path.join(root, 'skills', 'opencli-browser', 'references'), { recursive: true });
  fs.mkdirSync(path.join(root, 'skills', 'opencli-autofix'), { recursive: true });
  fs.mkdirSync(path.join(root, 'skills', 'smart-search'), { recursive: true });
  fs.writeFileSync(path.join(root, 'package.json'), '{"name":"@jackwener/opencli"}\n');
  fs.writeFileSync(path.join(root, 'skills', 'opencli-browser', 'SKILL.md'), [
    '---',
    'name: opencli-browser',
    'description: Browser control skill',
    'version: 1.2.3',
    '---',
    '',
    '# Browser',
    '',
    'Body.',
    '',
  ].join('\n'));
  fs.writeFileSync(path.join(root, 'skills', 'opencli-browser', 'references', 'targets.md'), '# Targets\n');
  fs.writeFileSync(path.join(root, 'skills', 'opencli-autofix', 'SKILL.md'), [
    '---',
    'name: opencli-autofix',
    'description: Fix adapters: keep scope narrow',
    '---',
    '',
  ].join('\n'));
  fs.writeFileSync(path.join(root, 'skills', 'smart-search', 'SKILL.md'), [
    '---',
    'name: smart-search',
    'description: Search skill',
    '---',
    '',
  ].join('\n'));
  return root;
}

describe('opencli skills content', () => {
  it('lists only opencli-prefixed skills', () => {
    const root = makePackageRoot();

    expect(listOpenCliSkills(root).map((skill) => skill.name)).toEqual([
      'opencli-autofix',
      'opencli-browser',
    ]);
    expect(listOpenCliSkills(root).find((skill) => skill.name === 'opencli-autofix')?.description)
      .toBe('Fix adapters: keep scope narrow');
  });

  it('reads a skill SKILL.md and reference file', () => {
    const root = makePackageRoot();

    expect(readOpenCliSkill('opencli-browser', '', root)).toMatchObject({
      skill: 'opencli-browser',
      path: 'SKILL.md',
    });
    expect(readOpenCliSkill('opencli-browser/references/targets.md', '', root)).toMatchObject({
      skill: 'opencli-browser',
      path: 'references/targets.md',
      content: '# Targets\n',
    });
    expect(readOpenCliSkill('opencli-browser', 'references/targets.md', root).content).toBe('# Targets\n');
  });

  it('rejects non-opencli skills and path traversal', () => {
    const root = makePackageRoot();

    expect(() => readOpenCliSkill('smart-search', '', root)).toThrow(ArgumentError);
    expect(() => readOpenCliSkill('opencli-browser/../smart-search/SKILL.md', '', root)).toThrow(ArgumentError);
    expect(() => readOpenCliSkill('opencli-browser', '../../package.json', root)).toThrow(ArgumentError);
  });
});

import { getRegistry } from '@jackwener/opencli/registry';
